import csv, html, json
from pathlib import Path
ROOT=Path(r'E:\agent-market-style-adaptive'); OUT=ROOT/'outputs/pandadata_exact_20260918_adaptive_only/weekly'
def rc(n):
    with (OUT/n).open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
s=json.loads((OUT/'run_summary.json').read_text(encoding='utf-8')); a=rc('latest_allocation.csv'); h=rc('latest_holdings.csv'); c=rc('holding_changes.csv'); lc=c[-1] if c else {}
def p(v): return f'{float(v)*100:.2f}%'
def e(v): return html.escape(str(v) if v not in (None,'') else '—')
annual=s['observed_adaptive_annual_return']; excess=s['annual_excess_return']; dd=s['comparison'][0]['max_drawdown']; sh=s['comparison'][0]['sharpe']; rm={'cold':'寒冷','warm':'温暖','overheated':'过热'}; regime=rm.get(lc.get('regime'),lc.get('regime','—'))
ar=''.join(f"<tr><td>{e(r.get('asset'))}</td><td>{p(r.get('actual_weight',0))}</td></tr>" for r in a)
hr=''.join(f"<tr><td>{e(r.get('symbol'))}</td><td>{e(r.get('name'))}</td><td>{e(r.get('sleeve'))}</td><td>{int(float(r.get('shares',0))):,}</td><td>{float(r.get('close',0)):.2f}</td></tr>" for r in h)
sig=f"{e(lc.get('execution_date'))} · {e(regime)} · 卖出 {e(lc.get('sells'))} · 买入 {e(lc.get('buys'))} · {e(lc.get('reasons'))}"
d=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>自适应策略信号</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#f4f6f8;color:#17202a;font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}}.wrap{{max-width:980px;margin:auto;padding:28px 20px 48px}}h1{{margin:0;font-size:28px}}.sub{{color:#6b7280;margin:6px 0 24px}}.grid{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:22px}}.card,section{{background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:16px}}section{{margin-top:14px}}h2{{font-size:16px;margin:0 0 12px}}.label{{color:#6b7280;font-size:12px}}.value{{font-size:24px;font-weight:700;margin-top:4px}}table{{width:100%;border-collapse:collapse}}th,td{{padding:9px 8px;border-bottom:1px solid #eef0f2;text-align:left}}th{{font-size:12px;color:#6b7280}}tr:last-child td{{border:0}}.signal{{font-weight:600;color:#0f5132;background:#ecfdf3;border:1px solid #bbf7d0;padding:12px;border-radius:8px;overflow-wrap:anywhere}}.meta{{color:#6b7280;font-size:12px;margin-top:18px}}@media(max-width:700px){{.grid{{grid-template-columns:repeat(2,1fr)}}.wrap{{padding:20px 12px}}}}</style></head><body><main class="wrap"><h1>自适应策略信号</h1><div class="sub">回测 {e(s.get('data_end'))} · 最新持仓 {e(h[0].get('date') if h else s.get('data_end'))} · 市场状态：{e(regime)}</div><div class="grid"><div class="card"><div class="label">年化收益</div><div class="value">{p(annual)}</div></div><div class="card"><div class="label">沪深300超额</div><div class="value">{p(excess)}</div></div><div class="card"><div class="label">最大回撤</div><div class="value">{p(dd)}</div></div><div class="card"><div class="label">夏普</div><div class="value">{sh:.2f}</div></div></div><section><h2>最近信号</h2><div class="signal">{sig}</div></section><section><h2>当前仓位</h2><table><thead><tr><th>类别</th><th>权重</th></tr></thead><tbody>{ar}</tbody></table></section><section><h2>最新持仓</h2><table><thead><tr><th>代码</th><th>名称</th><th>类别</th><th>数量</th><th>收盘价</th></tr></thead><tbody>{hr}</tbody></table></section><div class="meta">区间：{e(s.get('data_end'))} · 基准：沪深300</div></main></body></html>'''
(OUT/'report.html').write_text(d,encoding='utf-8'); print(len(d))